  let dt = viewT / f32(sampleCount);
  let sunCos = dot(rd, U.sunDir);

  var rayleighCol = vec3<f32>(0.0);
  var mieCol = vec3<f32>(0.0);
  var opticalR = 0.0; // 视线瑞利光学厚度(标量, 颜色在 beta 处体现)
  var opticalM = 0.0;

